import * as http from "node:http";

interface IncomingOrder {
  productId: string;
  quantity: number;
}

const server = http.createServer((req, res) => {
  const { method, url } = req;

  // 1. فحص المسار والـ Method
  if (url === "/api/health" && method === "GET") {
    res.writeHead(200, { "Content-Type": "application/json" });
    res.end(JSON.stringify({ status: "healthy", timestamp: new Date().toISOString() }));
    return;
  }

  // 2. استقبال بيانات في مسار الطلبات
  if (url === "/api/orders" && method === "POST") {
    let body = "";

    req.on("data", (chunk: Buffer) => {
      body += chunk.toString();
    });

    req.on("end", () => {
      try {
        const orderData: IncomingOrder = JSON.parse(body);

        // Validation بسيط
        if (!orderData.productId || typeof orderData.quantity !== "number") {
          res.writeHead(400, { "Content-Type": "application/json" });
          res.end(JSON.stringify({ error: "Invalid product data" }));
          return;
        }

        // إرجاع Response بالنجاح
        res.writeHead(201, { "Content-Type": "application/json" });
        res.end(JSON.stringify({
          message: "Order received successfully",
          orderId: "ord_12345",
          data: orderData
        }));
      } catch (err) {
        res.writeHead(400, { "Content-Type": "application/json" });
        res.end(JSON.stringify({ error: "Malformed JSON payload" }));
      }
    });
    return;
  }

  // في حالة طلب مسار غير موجود
  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Route not found" }));
});

server.listen(3000, () => {
  console.log("Server is running on port 3000");
});

