// src/config/environment.ts
import * as process from "node:process";

export interface ServerConfig {
  port: number;
  nodeEnv: "development" | "production" | "test";
  databaseUrl: string;
  isProduction: boolean;
}

export function loadEnvironmentConfig(): ServerConfig {
  const rawPort = process.env.PORT || "3000";
  const port = parseInt(rawPort, 10);

  if (Number.isNaN(port)) {
    console.error("Invalid PORT specified in environment variables.");
    process.exit(1);
  }

  const nodeEnv = (process.env.NODE_ENV as "development" | "production" | "test") || "development";
  const databaseUrl = process.env.DATABASE_URL;

  // التحقق الإلزامي من وجود عنوان قاعدة البيانات في الإنتاج
  if (!databaseUrl && nodeEnv === "production") {
    console.error("FATAL ERROR: DATABASE_URL is required in production mode.");
    process.exit(1);
  }

  return {
    port,
    nodeEnv,
    databaseUrl: databaseUrl || "postgres://localhost:5432/dev_db",
    isProduction: nodeEnv === "production"
  };
}

// src/app.ts
import { loadEnvironmentConfig } from "./config/environment.js";

const config = loadEnvironmentConfig();

console.log(`Application started in [${config.nodeEnv}] mode on port: ${config.port}`);
console.log(`Database connected target: ${config.databaseUrl}`);

