interface UserProfile {
  id: string;
  name: string;
}

interface UserOrders {
  userId: string;
  totalOrders: number;
}

// محاكاة جلب بيانات مستخدم من قاعدة البيانات (تستغرق 100ms)
async function fetchUserProfile(userId: string): Promise<UserProfile> {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({ id: userId, name: "Kareem Ali" });
    }, 100);
  });
}

// محاكاة جلب طلبات المستخدم (تستغرق 100ms)
async function fetchUserOrders(userId: string): Promise<UserOrders> {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({ userId, totalOrders: 15 });
    }, 100);
  });
}

// أسلوب خاطئ وبطيء: التنفيذ بالتسلسل (Sequential) — هياخد 200ms
export async function getDashboardDataSlow(userId: string) {
  const startTime = Date.now();

  const user = await fetchUserProfile(userId);   // بيستنى 100ms
  const orders = await fetchUserOrders(userId); // بيستنى 100ms تانية

  console.log(`Sequential execution took: ${Date.now() - startTime}ms`);
  return { user, orders };
}

// أسلوب هندسي صحيح وسريع: التنفيذ بالتوازي (Concurrent) — هياخد 100ms بس!
export async function getDashboardDataFast(userId: string) {
  const startTime = Date.now();

  // تشغيل الاستعلامين مع بعض في نفس اللحظة
  const [user, orders] = await Promise.all([
    fetchUserProfile(userId),
    fetchUserOrders(userId)
  ]);

  console.log(`Concurrent execution took: ${Date.now() - startTime}ms`);
  return { user, orders };
}

// التعامل مع احتمالية فشل جزء من العمليات بـ Promise.allSettled
export async function fetchMultipleServices(serviceUrls: string[]) {
  const results = await Promise.allSettled(
    serviceUrls.map((url) => fetch(url).then((res) => res.json()))
  );

  const successfulResponses = results
    .filter((r): r is PromiseFulfilledResult<any> => r.status === "fulfilled")
    .map((r) => r.value);

  const failedResponses = results
    .filter((r): r is PromiseRejectedResult => r.status === "rejected")
    .map((r) => r.reason);

  return { successfulResponses, failedResponses };
}

process.on("unhandledRejection", (reason, promise) => {
  console.error("Unhandled Rejection at:", promise, "reason:", reason);
});

