import * as fs from "node:fs";
import * as fsPromises from "node:fs/promises";
import * as path from "node:path";
import * as zlib from "node:zlib";
import * as crypto from "node:crypto";
import { pipeline } from "node:stream/promises";
import { EventEmitter } from "node:events";

// 1. إنشاء فئة للأحداث لتتبع العمليات
class LogCompressor extends EventEmitter {
  async compressLogFile(sourcePath: string, destDir: string): Promise<{ compressedPath: string; hash: string }> {
    const filename = path.basename(sourcePath);
    const compressedFilename = `${filename}.gz`;
    const targetPath = path.join(destDir, compressedFilename);

    // التأكد من وجود المجلد الهدف
    await fsPromises.mkdir(destDir, { recursive: true });

    this.emit("start", { source: sourcePath, destination: targetPath });

    // إنشاء الـ Streams
    const readStream = fs.createReadStream(sourcePath);
    const gzipStream = zlib.createGzip();
    const writeStream = fs.createWriteStream(targetPath);

    // حساب الـ Hash بالتوازي أثناء تدفق البيانات
    const hashGenerator = crypto.createHash("sha256");

    readStream.on("data", (chunk: Buffer) => {
      hashGenerator.update(chunk);
    });

    // استخدام pipeline لربط القراءة بالضغط بالكتابة بأمان
    await pipeline(readStream, gzipStream, writeStream);

    const fileHash = hashGenerator.digest("hex");

    this.emit("complete", { targetPath, fileHash });

    return { compressedPath: targetPath, hash: fileHash };
  }
}

// 2. استخدام الموديول واختبار الأحداث
async function runDemo() {
  const compressor = new LogCompressor();

  compressor.on("start", (info) => {
    console.log(`[EVENT] Starting compression of: ${info.source}`);
  });

  compressor.on("complete", (info) => {
    console.log(`[EVENT] Compression finished! SHA256: ${info.fileHash}`);
  });

  const sampleLogPath = path.resolve(process.cwd(), "temp_server.log");
  const outputDirectory = path.resolve(process.cwd(), "compressed_logs");

  // إنشاء ملف تجريبي مؤقت
  await fsPromises.writeFile(sampleLogPath, "2026-09-01 INFO: Server started.\n2026-09-01 DEBUG: Connection opened.\n");

  // تنفيذ الضغط عبر الـ Streams
  const result = await compressor.compressLogFile(sampleLogPath, outputDirectory);
  console.log(`Successfully created compressed archive at: ${result.compressedPath}`);

  // تنظيف الملف التجريبي
  await fsPromises.unlink(sampleLogPath);
}

runDemo().catch((err) => {
  console.error("Compression failed:", err);
});

