// 1. تعريف حالات وكيانات النظام (Domain Entities)
export type OrderStatus = "draft" | "confirmed" | "shipped" | "cancelled";

export interface UserEntity {
  id: string;
  email: string;
  passwordHash: string; // بيانات حساسة لا تخرج للـ Client
  role: "admin" | "customer";
  createdAt: Date;
}

// 2. تعريف الـ DTOs (Data Transfer Objects)
export interface CreateUserDto {
  email: string;
  passwordPlainText: string;
}

export interface UserPublicDto {
  id: string;
  email: string;
  role: "admin" | "customer";
}

// 3. تطبيق نمط النتيجة الموحد (Result Pattern)
export type Result<T, E = string> =
  | { success: true; value: T }
  | { success: false; error: E };

export function ok<T>(value: T): Result<T, never> {
  return { success: true, value };
}

export function fail<E>(error: E): Result<never, E> {
  return { success: false, error };
}

// 4. دالة Type Guard مخصصة لفحص البيانات المجهولة وقت التشغيل
export function isCreateUserDto(payload: unknown): payload is CreateUserDto {
  if (typeof payload !== "object" || payload === null) {
    return false;
  }

  const candidate = payload as Record<string, unknown>;

  return (
    typeof candidate.email === "string" &&
    candidate.email.includes("@") &&
    typeof candidate.passwordPlainText === "string" &&
    candidate.passwordPlainText.length >= 8
  );
}

// 5. طبقة الخدمة (Service Layer) باستخدام الـ Types
export class UserService {
  private users: UserEntity[] = [];

  public async register(payload: unknown): Promise<Result<UserPublicDto, string>> {
    // التحقق من نوع البيانات باستخدام الـ Type Guard
    if (!isCreateUserDto(payload)) {
      return fail("Invalid registration payload: email and strong password required.");
    }

    // فحص عدم تكرار البريد
    const existing = this.users.find((u) => u.email === payload.email);
    if (existing) {
      return fail("Email is already registered.");
    }

    const newUser: UserEntity = {
      id: `usr_${Date.now()}`,
      email: payload.email,
      passwordHash: `hashed_${payload.passwordPlainText}`, // مجرد محاكاة
      role: "customer",
      createdAt: new Date()
    };

    this.users.push(newUser);

    // تحويل الكائن الداخلي لـ Public DTO
    const publicUser: UserPublicDto = {
      id: newUser.id,
      email: newUser.email,
      role: newUser.role
    };

    return ok(publicUser);
  }
}

import * as http from "node:http";
import { URL } from "node:url";

const server = http.createServer((req, res) => {
  // تحليل الـ URL والـ Query Parameters
  const baseURL = `http://${req.headers.host || "localhost:3000"}`;
  const parsedUrl = new URL(req.url || "/", baseURL);
  const pathname = parsedUrl.pathname;
  const method = req.method;

  // 1. مسار الـ Login وتعيين Secure HttpOnly Cookie
  if (pathname === "/api/login" && method === "POST") {
    res.writeHead(200, {
      "Content-Type": "application/json",
      "Set-Cookie": "session_id=sec_99182a; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=3600"
    });
    res.end(JSON.stringify({ message: "Authenticated successfully" }));
    return;
  }

  // 2. مسار المنتجات مع Pagination عبر الـ Query Parameters (GET /api/products?page=1&limit=10)
  if (pathname === "/api/products" && method === "GET") {
    const page = parseInt(parsedUrl.searchParams.get("page") || "1", 10);
    const limit = parseInt(parsedUrl.searchParams.get("limit") || "10", 10);

    const mockProducts = [
      { id: "p1", name: "Mechanical Keyboard", price: 120 },
      { id: "p2", name: "Ergonomic Mouse", price: 80 }
    ];

    res.writeHead(200, {
      "Content-Type": "application/json",
      "Cache-Control": "public, max-age=60" // توجيه المتصفح لتخزين الكاش لمدة دقيقة
    });

    res.end(JSON.stringify({
      meta: { page, limit, total: 2 },
      data: mockProducts
    }));
    return;
  }

  // 3. مسار حذف مورد بـ DELETE مع إرجاع 204 No Content
  if (pathname.startsWith("/api/products/") && method === "DELETE") {
    const productId = pathname.split("/")[3];

    if (!productId) {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "Product ID is missing in path" }));
      return;
    }

    // إرجاع 204 بنجاح وبدون أي Body
    res.writeHead(204);
    res.end();
    return;
  }

  // 4. في حالة المسار غير موجود
  res.writeHead(404, { "Content-Type": "application/json" });
  res.end(JSON.stringify({ error: "Resource not found on this server" }));
});

server.listen(3000, () => {
  console.log("HTTP Deep Dive Server running on port 3000");
});

