// 1. تعريف النماذج والواجهات الموحدة
export interface PaginationMeta {
  page: number;
  limit: number;
  totalRecords: number;
  totalPages: number;
  hasNextPage: boolean;
}

export interface RestResponse<T> {
  success: boolean;
  data: T;
  meta?: PaginationMeta;
  error?: {
    code: string;
    message: string;
  };
}

export interface ProductQueryFilter {
  category?: string;
  minPrice?: number;
  maxPrice?: number;
  sortBy?: "price" | "createdAt";
  order?: "asc" | "desc";
  page?: number;
  limit?: number;
}

// 2. دالة مساعدة لإنشاء استجابة الترقيم القياسية
export function createPaginatedResponse<T>(
  items: T[],
  totalRecords: number,
  page: number,
  limit: number
): RestResponse<T[]> {
  const totalPages = Math.ceil(totalRecords / limit);

  return {
    success: true,
    data: items,
    meta: {
      page,
      limit,
      totalRecords,
      totalPages,
      hasNextPage: page < totalPages
    }
  };
}

// 3. محاكاة فحص مفتاح منع التكرار (Idempotency Manager)
export class IdempotencyManager {
  private cache = new Map<string, { statusCode: number; responseBody: unknown }>();

  public getExistingResult(key: string) {
    return this.cache.get(key);
  }

  public saveResult(key: string, statusCode: number, responseBody: unknown) {
    this.cache.set(key, { statusCode, responseBody });
  }
}

