// 1. ملف الـ Controller (src/controllers/product.controller.ts)
import { Request, Response } from "express";

interface Product {
  id: string;
  name: string;
  price: number;
}

// محاكاة لقاعدة بيانات محلية
const productsDatabase: Product[] = [
  { id: "1", name: "Laptop Pro", price: 1200 },
  { id: "2", name: "Wireless Mouse", price: 25 }
];

export class ProductController {
  // GET /api/v1/products
  public static getAll(req: Request, res: Response): void {
    const maxPrice = req.query.maxPrice ? Number(req.query.maxPrice) : undefined;

    let results = productsDatabase;
    if (maxPrice !== undefined && !Number.isNaN(maxPrice)) {
      results = results.filter((p) => p.price <= maxPrice);
    }

    res.status(200).json({
      success: true,
      count: results.length,
      data: results
    });
  }

  // GET /api/v1/products/:id
  public static getById(req: Request, res: Response): void {
    const { id } = req.params;
    const product = productsDatabase.find((p) => p.id === id);

    if (!product) {
      res.status(404).json({
        success: false,
        error: { code: "NOT_FOUND", message: `Product with ID '${id}' not found.` }
      });
      return;
    }

    res.status(200).json({
      success: true,
      data: product
    });
  }

  // POST /api/v1/products
  public static create(req: Request, res: Response): void {
    const { name, price } = req.body;

    if (!name || typeof price !== "number") {
      res.status(400).json({
        success: false,
        error: { code: "VALIDATION_FAILED", message: "Name and numeric price are required." }
      });
      return;
    }

    const newProduct: Product = {
      id: String(productsDatabase.length + 1),
      name,
      price
    };

    productsDatabase.push(newProduct);

    res.status(201).json({
      success: true,
      data: newProduct
    });
  }
}

