import express, { Request, Response, NextFunction } from "express";
import { z, ZodError } from "zod";
import * as crypto from "node:crypto";

const app = express();
app.use(express.json());

// 1. Custom Middleware: إضافة Correlation / Request ID لكل طلب
export function correlationIdMiddleware(req: Request, res: Response, next: NextFunction) {
  const requestId = (req.headers["x-request-id"] as string) || crypto.randomUUID();
  req.headers["x-request-id"] = requestId;
  res.setHeader("X-Request-ID", requestId);
  next();
}

// 2. Custom Middleware: قياس وحساب زمن الاستجابة (Performance Logger)
export function requestTimingMiddleware(req: Request, res: Response, next: NextFunction) {
  const start = process.hrtime.bigint();

  res.on("finish", () => {
    const end = process.hrtime.bigint();
    const durationMs = Number(end - start) / 1_000_000;
    const reqId = req.headers["x-request-id"];
    console.log(`[REQ ${reqId}] ${req.method} ${req.originalUrl} - ${res.statusCode} (${durationMs.toFixed(2)}ms)`);
  });

  next();
}

// 3. بناء Generic Validation Middleware يقبل Zod Schemas
export function validateRequest(schema: {
  body?: z.ZodTypeAny;
  query?: z.ZodTypeAny;
  params?: z.ZodTypeAny;
}) {
  return async (req: Request, res: Response, next: NextFunction): Promise<void> => {
    try {
      if (schema.body) {
        req.body = await schema.body.parseAsync(req.body);
      }
      if (schema.query) {
        req.query = await schema.query.parseAsync(req.query);
      }
      if (schema.params) {
        req.params = await schema.params.parseAsync(req.params);
      }
      next();
    } catch (error) {
      if (error instanceof ZodError) {
        const formattedErrors = error.errors.map((err) => ({
          field: err.path.join("."),
          message: err.message,
          rule: err.code
        }));

        res.status(400).json({
          success: false,
          error: {
            code: "VALIDATION_ERROR",
            message: "Incoming request payload failed schema validation.",
            details: formattedErrors
          }
        });
        return;
      }
      next(error);
    }
  };
}

// 4. تعريف الـ Schemas واستنتاج الـ Types
export const CreateProductSchema = z.object({
  title: z.string().min(3, "Title must be at least 3 characters").max(100),
  price: z.number().positive("Price must be a positive number"),
  category: z.enum(["electronics", "books", "clothing"]),
  inStock: z.boolean().default(true),
  tags: z.array(z.string()).min(1, "At least one tag is required")
});

export type CreateProductInput = z.infer<typeof CreateProductSchema>;

// 5. تطبيق الـ Middleware على الـ Route
app.use(correlationIdMiddleware);
app.use(requestTimingMiddleware);

app.post(
  "/api/v1/products",
  validateRequest({ body: CreateProductSchema }),
  (req: Request, res: Response) => {
    // هنا نضمن 100% أن البيانات مطابقة ومفحوصة تماماً
    const productData: CreateProductInput = req.body;

    res.status(201).json({
      success: true,
      message: "Product created successfully",
      data: {
        id: `prod_${Date.now()}`,
        ...productData
      }
    });
  }
);

const PORT = 3000;
app.listen(PORT, () => console.log(`Validation Server running on port ${PORT}`));

// ==========================================
// 1. Types & Domain Model (src/modules/users/user.types.ts)
// ==========================================
export interface User {
  id: string;
  email: string;
  fullName: string;
  walletBalance: number;
  createdAt: Date;
}

export interface CreateUserInput {
  email: string;
  fullName: string;
  initialDeposit: number;
}

// ==========================================
// 2. Repository Interface & Implementation (src/modules/users/user.repository.ts)
// ==========================================
export interface IUserRepository {
  findByEmail(email: string): Promise<User | null>;
  findById(id: string): Promise<User | null>;
  create(data: CreateUserInput): Promise<User>;
  updateBalance(id: string, newBalance: number): Promise<void>;
}

export class InMemoryUserRepository implements IUserRepository {
  private users: User[] = [];

  async findByEmail(email: string): Promise<User | null> {
    return this.users.find((u) => u.email === email) || null;
  }

  async findById(id: string): Promise<User | null> {
    return this.users.find((u) => u.id === id) || null;
  }

  async create(data: CreateUserInput): Promise<User> {
    const user: User = {
      id: `usr_${Date.now()}`,
      email: data.email,
      fullName: data.fullName,
      walletBalance: data.initialDeposit,
      createdAt: new Date()
    };
    this.users.push(user);
    return user;
  }

  async updateBalance(id: string, newBalance: number): Promise<void> {
    const user = await this.findById(id);
    if (user) {
      user.walletBalance = newBalance;
    }
  }
}

// ==========================================
// 3. Service Layer (Pure Business Logic) (src/modules/users/user.service.ts)
// ==========================================
export class UserService {
  // حقن التبعية عبر الـ Constructor
  constructor(private readonly userRepository: IUserRepository) {}

  async registerUser(input: CreateUserInput): Promise<User> {
    // 1. فحص قاعدة بيزنس: هل الإيميل مسجل من قبل؟
    const existingUser = await this.userRepository.findByEmail(input.email);
    if (existingUser) {
      throw new Error("EMAIL_ALREADY_EXISTS");
    }

    // 2. فحص قاعدة بيزنس: الحد الأدنى للإيداع الأولي
    if (input.initialDeposit < 50) {
      throw new Error("MINIMUM_DEPOSIT_REQUIRED");
    }

    // 3. حفظ المستخدم في قاعدة البيانات عبر الـ Repository
    return await this.userRepository.create(input);
  }

  async transferFunds(senderId: string, receiverId: string, amount: number): Promise<void> {
    if (amount <= 0) {
      throw new Error("INVALID_TRANSFER_AMOUNT");
    }

    const sender = await this.userRepository.findById(senderId);
    const receiver = await this.userRepository.findById(receiverId);

    if (!sender || !receiver) {
      throw new Error("USER_NOT_FOUND");
    }

    if (sender.walletBalance < amount) {
      throw new Error("INSUFFICIENT_FUNDS");
    }

    await this.userRepository.updateBalance(sender.id, sender.walletBalance - amount);
    await this.userRepository.updateBalance(receiver.id, receiver.walletBalance + amount);
  }
}

// ==========================================
// 4. Controller Layer (HTTP Layer) (src/modules/users/user.controller.ts)
// ==========================================
import { Request, Response } from "express";

export class UserController {
  constructor(private readonly userService: UserService) {}

  public register = async (req: Request, res: Response): Promise<void> => {
    try {
      const { email, fullName, initialDeposit } = req.body;
      const user = await this.userService.registerUser({ email, fullName, initialDeposit });

      res.status(201).json({
        success: true,
        message: "User registered successfully",
        data: user
      });
    } catch (error: any) {
      if (error.message === "EMAIL_ALREADY_EXISTS") {
        res.status(409).json({ success: false, error: { code: "CONFLICT", message: "Email is already in use." } });
        return;
      }
      if (error.message === "MINIMUM_DEPOSIT_REQUIRED") {
        res.status(422).json({ success: false, error: { code: "UNPROCESSABLE", message: "Initial deposit must be >= 50 EGP." } });
        return;
      }
      res.status(500).json({ success: false, error: { code: "INTERNAL_ERROR", message: "An unexpected error occurred." } });
    }
  };
}

