import { Pool, PoolClient } from "pg";

export interface TransferRequest {
  senderAccountId: string;
  receiverAccountId: string;
  amount: number;
}

export class BankService {
  constructor(private readonly dbPool: Pool) {}

  public async executeTransfer(transfer: TransferRequest): Promise<{ transactionId: string }> {
    if (transfer.amount <= 0) {
      throw new Error("Transfer amount must be strictly positive.");
    }

    // 1. حجز اتصال مخصص من الـ Pool للمعاملة
    const client: PoolClient = await this.dbPool.connect();

    try {
      // 2. بدء المعاملة
      await client.query("BEGIN;");

      // لمنع الـ Deadlocks: نقفل الحسابين دائماً بالترتيب الأبجدي للمعرفات
      const [firstId, secondId] = [transfer.senderAccountId, transfer.receiverAccountId].sort();

      // 3. قفل الحسابين متشائماً (Pessimistic Row-Level Lock)
      const accountsRes = await client.query(
        `SELECT id, balance FROM accounts WHERE id IN ($1, $2) FOR UPDATE;`,
        [firstId, secondId]
      );

      if (accountsRes.rows.length !== 2) {
        throw new Error("One or both accounts do not exist.");
      }

      const sender = accountsRes.rows.find((a) => a.id === transfer.senderAccountId);
      const receiver = accountsRes.rows.find((a) => a.id === transfer.receiverAccountId);

      // 4. فحص شرط البيزنس: هل الرصيد كافٍ؟
      const currentSenderBalance = Number(sender.balance);
      if (currentSenderBalance < transfer.amount) {
        throw new Error("INSUFFICIENT_FUNDS: Sender account balance is inadequate.");
      }

      // 5. خصم الرصيد من الراسل
      await client.query(
        `UPDATE accounts SET balance = balance - $1, updated_at = NOW() WHERE id = $2;`,
        [transfer.amount, transfer.senderAccountId]
      );

      // 6. إضافة الرصيد للمستلم
      await client.query(
        `UPDATE accounts SET balance = balance + $1, updated_at = NOW() WHERE id = $2;`,
        [transfer.amount, transfer.receiverAccountId]
      );

      // 7. تسجيل حركة التحويل في جدول السجلات (Audit Log)
      const auditRes = await client.query(
        `INSERT INTO transfer_logs (sender_id, receiver_id, amount, status) 
         VALUES ($1, $2, $3, 'completed') RETURNING id;`,
        [transfer.senderAccountId, transfer.receiverAccountId, transfer.amount]
      );

      // 8. اعتماد المعاملة نهائياً
      await client.query("COMMIT;");

      return { transactionId: auditRes.rows[0].id };
    } catch (error) {
      // في حالة أي خطأ: التراجع الفوري عن كل العمليات
      await client.query("ROLLBACK;");
      throw error;
    } finally {
      // 9. تحرير وإرجاع الاتصال للـ Pool دائماً
      client.release();
    }
  }
}

