// 1. موديول الاتصال بقاعدة البيانات (src/infrastructure/database.ts)
import pg from "pg";
const { Pool } = pg;

export interface DatabaseConfig {
  connectionString: string;
  maxConnections: number;
  idleTimeoutMillis: number;
  connectionTimeoutMillis: number;
  ssl?: boolean;
}

export class DatabasePool {
  private static instance: pg.Pool | null = null;

  public static initialize(config: DatabaseConfig): pg.Pool {
    if (!DatabasePool.instance) {
      DatabasePool.instance = new Pool({
        connectionString: config.connectionString,
        max: config.maxConnections || 20,
        idleTimeoutMillis: config.idleTimeoutMillis || 30000,
        connectionTimeoutMillis: config.connectionTimeoutMillis || 2000,
        ssl: config.ssl ? { rejectUnauthorized: false } : undefined
      });

      DatabasePool.instance.on("error", (err) => {
        console.error("Unexpected error on idle database client:", err);
      });
    }
    return DatabasePool.instance;
  }

  public static getPool(): pg.Pool {
    if (!DatabasePool.instance) {
      throw new Error("DatabasePool has not been initialized. Call initialize() first.");
    }
    return DatabasePool.instance;
  }
}

// 2. مستودع المستخدمين (src/repositories/postgres-user.repository.ts)
export interface UserDbRecord {
  id: string;
  email: string;
  full_name: string;
  wallet_balance: string; // pg returns numeric as string to preserve precision
  created_at: Date;
}

export class PostgresUserRepository {
  constructor(private readonly pool: pg.Pool) {}

  public async findByEmail(email: string): Promise<UserDbRecord | null> {
    const query = `
      SELECT id, email, full_name, wallet_balance, created_at 
      FROM users 
      WHERE email = $1;
    `;
    const result = await this.pool.query<UserDbRecord>(query, [email]);
    return result.rows[0] || null;
  }

  public async createUser(data: { email: string; fullName: string; initialBalance: number }): Promise<UserDbRecord> {
    const query = `
      INSERT INTO users (email, full_name, wallet_balance) 
      VALUES ($1, $2, $3) 
      RETURNING id, email, full_name, wallet_balance, created_at;
    `;
    const values = [data.email, data.fullName, data.initialBalance];

    try {
      const result = await this.pool.query<UserDbRecord>(query, values);
      return result.rows[0];
    } catch (error: any) {
      // فحص كود خطأ تكرار السجل في PostgreSQL (Unique Violation)
      if (error.code === "23505") {
        throw new Error("DUPLICATE_EMAIL");
      }
      // فحص كود مخالفة القيود (Check Violation)
      if (error.code === "23514") {
        throw new Error("INVALID_DATA_CONSTRAINT");
      }
      throw error;
    }
  }

  // تنفيذ معاملة بنكية مجمعة (Atomic Transaction)
  public async transferBalance(senderId: string, receiverId: string, amount: number): Promise<void> {
    const client = await this.pool.connect();

    try {
      await client.query("BEGIN;");

      // 1. خصم الرصيد مع التحقق من عدم الوصول لرصيد سالب
      const deductRes = await client.query(
        `UPDATE users SET wallet_balance = wallet_balance - $1 
         WHERE id = $2 AND wallet_balance >= $1 
         RETURNING id;`,
        [amount, senderId]
      );

      if (deductRes.rowCount === 0) {
        throw new Error("INSUFFICIENT_FUNDS_OR_USER_NOT_FOUND");
      }

      // 2. إضافة الرصيد للمستلم
      const addRes = await client.query(
        `UPDATE users SET wallet_balance = wallet_balance + $1 
         WHERE id = $2 
         RETURNING id;`,
        [amount, receiverId]
      );

      if (addRes.rowCount === 0) {
        throw new Error("RECEIVER_NOT_FOUND");
      }

      await client.query("COMMIT;");
    } catch (err) {
      await client.query("ROLLBACK;");
      throw err;
    } finally {
      client.release();
    }
  }
}

pool.on("connect", (client) => {
  client.on("notice", (msg) => console.warn("DB Notice:", msg.message));
});

