import { Kysely, PostgresDialect } from "kysely";
import pg from "pg";

// 1. تعريف أنواع جداول قاعدة البيانات للـ Type Safety
export interface UserTable {
  id: string;
  email: string;
  full_name: string;
}

export interface OrderTable {
  id: string;
  user_id: string;
  total_price: number;
  status: "pending" | "completed" | "cancelled";
}

export interface DatabaseSchema {
  users: UserTable;
  orders: OrderTable;
}

// 2. تهيئة Kysely
export const db = new Kysely<DatabaseSchema>({
  dialect: new PostgresDialect({
    pool: new pg.Pool({ connectionString: process.env.DATABASE_URL })
  })
});

// 3. كتابة استعلام واضح و Type-Safe مع التجميع
export async function getUserWithOrderStats(userId: string) {
  return await db
    .selectFrom("users")
    .innerJoin("orders", "orders.user_id", "users.id")
    .where("users.id", "=", userId)
    .where("orders.status", "=", "completed")
    .select([
      "users.id as userId",
      "users.full_name as fullName",
      (eb) => eb.fn.count("orders.id").as("completedOrdersCount"),
      (eb) => eb.fn.sum("orders.total_price").as("totalSpent")
    ])
    .groupBy(["users.id", "users.full_name"])
    .executeTakeFirst();
}

