import { PrismaClient } from "@prisma/client";

const prisma = new PrismaClient();

// تنفيذ المعاملة وحساب الإحصائيات في Prisma
export async function createOrderAndDeductBalance(
  userId: string,
  totalAmount: number,
  productItems: { productId: string; quantity: number }[]
) {
  // استخدام $transaction لإدارة المعاملة تلقائياً
  return await prisma.$transaction(async (tx) => {
    // 1. فحص رصيد المستخدم وخصم المبلغ
    const user = await tx.user.update({
      where: { id: userId },
      data: {
        walletBalance: { decrement: totalAmount }
      }
    });

    // 2. إنشاء الطلب وعناصره في خطوة متداخلة (Nested Write)
    const order = await tx.order.create({
      data: {
        userId: user.id,
        totalPrice: totalAmount,
        status: "completed",
        items: {
          create: productItems.map((item) => ({
            productId: item.productId,
            quantity: item.quantity
          }))
        }
      },
      include: {
        items: true
      }
    });

    return order;
  });
}

