  {
    $group: {
      _id: "$categories",
      averageRating: { $avg: "$ratings.score" },
      totalReviewsCount: { $sum: 1 },
      totalProductsCount: { $addToSet: "$_id" }
    }
  },

  // المرحلة 5: تنسيق شكل المخرجات النهائية
  {
    $project: {
      category: "$_id",
      averageRating: { $round: ["$averageRating", 2] },
      totalReviewsCount: 1,
      uniqueProductsCount: { $size: "$totalProductsCount" },
      _id: 0
    }
  },

  // المرحلة 6: ترتيب بالتصنيف الأعلى تقييماً
  { $sort: { averageRating: -1 } }
]);

