import mongoose, { Schema, model, InferSchemaType, HydratedDocument } from "mongoose";

// 1. تعريف الـ Schema مع القيود والفهارس المدمجة
const ProductSchema = new Schema(
  {
    sku: { 
      type: String, 
      required: [true, "Product SKU is mandatory"], 
      unique: true, 
      uppercase: true, 
      trim: true 
    },
    title: { type: String, required: true, trim: true, minlength: 3, maxlength: 200 },
    price: { type: Number, required: true, min: [0, "Price cannot be negative"] },
    stock: { type: Number, required: true, min: 0, default: 0 },
    category: { type: String, required: true, index: true },
    tags: [{ type: String, lowercase: true }],
    isPublished: { type: Boolean, default: false }
  },
  {
    timestamps: true, // يضيف حقول createdAt و updatedAt تلقائياً
    versionKey: false // إزالة حقل __v الافتراضي
  }
);

// 2. إنشاء فهرس مركب لتسريع البحث بالتصنيف مع الترتيب بالسعر
ProductSchema.index({ category: 1, price: 1 });

// 3. Lifecycle Hook: تنسيق البيانات والتحقق قبل الحفظ (Pre-save Hook)
ProductSchema.pre("save", function (next) {
  if (this.isModified("title")) {
    this.title = this.title.replace(/\s+/g, " "); // إزالة المسافات الزائدة
  }
  next();
});

// استنتاج الأنواع وتصدير الموديل
export type IProduct = InferSchemaType<typeof ProductSchema>;
export type ProductHydrated = HydratedDocument<IProduct>;
export const ProductModel = model<IProduct>("Product", ProductSchema);

// 4. فئة المستودع (Repository Layer) للتعامل مع Mongoose
export class MongoProductRepository {
  // جلب المنتجات السريع باستخدام .lean()
  public async findByCategory(category: string, limit = 20): Promise<IProduct[]> {
    return await ProductModel.find({ category, isPublished: true })
      .sort({ price: 1 })
      .limit(limit)
      .lean() // تحسين الأداء بنسبة 5x
      .exec();
  }

  // إضافة منتج جديد مع الـ Validation التلقائي
  public async createProduct(data: IProduct): Promise<IProduct> {
    const product = new ProductModel(data);
    await product.save();
    return product.toObject();
  }

  // تعديل ذري آمن للمخزون
  public async deductStock(productId: string, quantity: number): Promise<boolean> {
    const result = await ProductModel.updateOne(
      { _id: productId, stock: { $gte: quantity } },
      { $inc: { stock: -quantity } }
    ).exec();

    return result.modifiedCount > 0;
  }
}

