import bcrypt from "bcryptjs";
import jwt, { JwtPayload } from "jsonwebtoken";
import { Request, Response, NextFunction } from "express";

// 1. إعدادات ومفاتيح التشفير
const JWT_SECRET = process.env.JWT_SECRET || "super-secret-production-key-at-least-32-chars";
const ACCESS_TOKEN_EXPIRY = "15m";
const BCRYPT_SALT_ROUNDS = 12;

export interface TokenPayload extends JwtPayload {
  userId: string;
  email: string;
  role: "admin" | "customer";
}

// 2. دوال مساعدة لأمان كلمات المرور
export class SecurityUtils {
  // تشفير كلمة المرور مع توليد Salt عشوائي تلقائياً
  public static async hashPassword(passwordPlainText: string): Promise<string> {
    return await bcrypt.hash(passwordPlainText, BCRYPT_SALT_ROUNDS);
  }

  // التحقق من صحة كلمة المرور ومقارنة الـ Hashes
  public static async verifyPassword(plainText: string, passwordHash: string): Promise<boolean> {
    return await bcrypt.compare(plainText, passwordHash);
  }

  // توليد Access Token قصير الأجل
  public static generateAccessToken(payload: Omit<TokenPayload, "iat" | "exp">): string {
    return jwt.sign(payload, JWT_SECRET, {
      expiresIn: ACCESS_TOKEN_EXPIRY,
      algorithm: "HS256"
    });
  }

  // فحص والتحقق من توقيع الـ JWT
  public static verifyAccessToken(token: string): TokenPayload {
    return jwt.verify(token, JWT_SECRET, { algorithms: ["HS256"] }) as TokenPayload;
  }
}

// 3. توسيع كائن Express Request لحمل بيانات المستخدم الموثق
declare global {
  namespace Express {
    interface Request {
      user?: TokenPayload;
    }
  }
}

// 4. حارس المصادقة (Authentication Guard Middleware)
export function requireAuth(req: Request, res: Response, next: NextFunction): void {
  const authHeader = req.headers.authorization;

  // التحقق من وجود ترويسة Bearer Token
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    res.status(401).json({
      success: false,
      error: { code: "UNAUTHORIZED", message: "Authentication required. Missing Bearer token." }
    });
    return;
  }

  const token = authHeader.split(" ")[1];

  try {
    const decoded = SecurityUtils.verifyAccessToken(token);
    req.user = decoded; // إرفاق بيانات المستخدم في كائن الطلب لاستخدامها في الـ Controllers
    next();
  } catch (error: any) {
    if (error.name === "TokenExpiredError") {
      res.status(401).json({
        success: false,
        error: { code: "TOKEN_EXPIRED", message: "Access token has expired. Please refresh." }
      });
      return;
    }

    res.status(401).json({
      success: false,
      error: { code: "INVALID_TOKEN", message: "Access token signature is invalid." }
    });
  }
}

import express, { Request, Response, NextFunction } from "express";
import helmet from "helmet";
import cors from "cors";
import rateLimit from "express-rate-limit";
import { requireAuth } from "./auth.middleware.js";

const app = express();

// 1. تطبيق ترويسات الأمان القياسية
app.use(helmet());

// 2. إعدادات CORS الصارمة والمخصصة للنطاق المعتمد بس
app.use(
  cors({
    origin: process.env.ALLOWED_ORIGIN || "https://dashboard.myshop.com",
    methods: ["GET", "POST", "PUT", "PATCH", "DELETE"],
    allowedHeaders: ["Content-Type", "Authorization", "X-Request-ID"],
    credentials: true, // السماح بإرسال الـ Cookies الموثقة
    maxAge: 86400 // تخزين الـ Preflight في الكاش لمدة يوم
  })
);

app.use(express.json({ limit: "50kb" })); // تقييد حجم الـ Body لحماية الذاكرة

// 3. Rate Limiter مخصص لحماية مسار تسجيل الدخول من التخمين
export const authRateLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 دقيقة
  max: 5, // 5 محاولات فقط لكل IP
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    success: false,
    error: {
      code: "RATE_LIMIT_EXCEEDED",
      message: "Too many login attempts from this IP. Please try again after 15 minutes."
    }
  }
});

// 4. دالة بناء Middleware لفحص رتب وأدوار المستخدمين (RBAC Guard)
export function requireRoles(...allowedRoles: Array<"admin" | "manager" | "customer">) {
  return (req: Request, res: Response, next: NextFunction): void => {
    // نفترض أن requireAuth تم تشغيله أولاً وقام بتعبئة req.user
    if (!req.user) {
      res.status(401).json({
        success: false,
        error: { code: "UNAUTHORIZED", message: "Authentication is required." }
      });
      return;
    }

    if (!allowedRoles.includes(req.user.role)) {
      res.status(403).json({
        success: false,
        error: {
          code: "FORBIDDEN",
          message: `Access denied. Requires one of roles: [${allowedRoles.join(", ")}]`
        }
      });
      return;
    }

    next();
  };
}

// 5. مسار إداري محمي برتبة Admin بس
app.delete(
  "/api/v1/system/purge-cache",
  requireAuth,
  requireRoles("admin"),
  (req: Request, res: Response) => {
    res.status(200).json({ success: true, message: "System cache cleared by Administrator." });
  }
);

// 6. مسار مع فحص الملكية (Ownership Authorization)
app.patch(
  "/api/v1/articles/:articleId",
  requireAuth,
  async (req: Request, res: Response): Promise<void> => {
    const { articleId } = req.params;
    const currentUserId = req.user!.userId;
    const currentUserRole = req.user!.role;

    // محاكاة استرجاع المقال من قاعدة البيانات
    const article = { id: articleId, title: "Backend Security", authorId: "usr_99" };

    // التحقق: إما أن تكون Admin أو أن تكون أنت صاحب المقال
    const isOwner = article.authorId === currentUserId;
    const isAdmin = currentUserRole === "admin";

    if (!isOwner && !isAdmin) {
      res.status(403).json({
        success: false,
        error: { code: "FORBIDDEN", message: "You do not have permission to edit this article." }
      });
      return;
    }

    res.status(200).json({
      success: true,
      message: "Article updated successfully."
    });
  }
);

const PORT = 3000;
app.listen(PORT, () => console.log(`Security Server running on port ${PORT}`));

