import express, { Request, Response, NextFunction } from "express";

// 1. الفئة الأساسية للأخطاء التشغيلية (Base AppError)
export class AppError extends Error {
  public readonly statusCode: number;
  public readonly errorCode: string;
  public readonly isOperational: boolean;
  public readonly details?: unknown;

  constructor(message: string, statusCode = 500, errorCode = "INTERNAL_ERROR", details?: unknown) {
    super(message);
    this.statusCode = statusCode;
    this.errorCode = errorCode;
    this.isOperational = true; // علامة تميز الأخطاء التشغيلية
    this.details = details;

    // الحفاظ على الـ Stack Trace الصحيح
    Error.captureStackTrace(this, this.constructor);
  }
}

// 2. فئات الأخطاء المشتقة الأكثر شيوعاً
export class BadRequestError extends AppError {
  constructor(message = "Bad Request", errorCode = "BAD_REQUEST", details?: unknown) {
    super(message, 400, errorCode, details);
  }
}

export class UnauthorizedError extends AppError {
  constructor(message = "Authentication required", errorCode = "UNAUTHORIZED") {
    super(message, 401, errorCode);
  }
}

export class ForbiddenError extends AppError {
  constructor(message = "Access forbidden", errorCode = "FORBIDDEN") {
    super(message, 403, errorCode);
  }
}

export class NotFoundError extends AppError {
  constructor(message = "Resource not found", errorCode = "NOT_FOUND") {
    super(message, 404, errorCode);
  }
}

export class ConflictError extends AppError {
  constructor(message = "Conflict in resource state", errorCode = "CONFLICT") {
    super(message, 409, errorCode);
  }
}

// 3. Wrapper لالتقاط أخطاء الدوال اللاتزامنية تلقائياً (Async Handler)
export function asyncHandler(fn: (req: Request, res: Response, next: NextFunction) => Promise<any>) {
  return (req: Request, res: Response, next: NextFunction) => {
    fn(req, res, next).catch(next); // يمرر أي خطأ Async تلقائياً لـ next(err)
  };
}

// 4. الـ Error Handling Middleware المركزي
export function errorHandlerMiddleware(
  err: Error | AppError,
  req: Request,
  res: Response,
  next: NextFunction
): void {
  const isProduction = process.env.NODE_ENV === "production";

  // فحص هل الخطأ تشغيلي ومعروف (Operational AppError)
  if (err instanceof AppError) {
    res.status(err.statusCode).json({
      success: false,
      error: {
        code: err.errorCode,
        message: err.message,
        details: err.details || null,
        // في بيئة التطوير بس نظهر الـ Stack Trace للمساعدة في التصحيح
        ...(!isProduction && { stack: err.stack })
      }
    });
    return;
  }

  // في حالة أخطاء المبرمج غير المتوقعة (Programmer Errors / Bugs)
  console.error("FATAL UNEXPECTED ERROR:", err);

  res.status(500).json({
    success: false,
    error: {
      code: "INTERNAL_SERVER_ERROR",
      message: isProduction ? "An unexpected internal error occurred." : err.message,
      ...(!isProduction && { stack: err.stack })
    }
  });
}

// 5. تطبيق الـ Middleware في تطبيق Express
const app = express();
app.use(express.json());

// مسار يوضح إلقاء خطأ تشغيلي نظيف
app.get(
  "/api/v1/users/:id",
  asyncHandler(async (req: Request, res: Response) => {
    const { id } = req.params;

    if (id === "0") {
      throw new NotFoundError(`User with ID '${id}' does not exist.`, "USER_NOT_FOUND");
    }

    res.status(200).json({ success: true, data: { id, name: "Ali" } });
  })
);

// تسجيل الميدلوير المركزي في نهاية التطبيق بعد كل الـ Routes
app.use(errorHandlerMiddleware);

// 6. صمامات الأمان على مستوى العملية (Process Level Safeguards)
process.on("unhandledRejection", (reason: unknown) => {
  console.error("CRITICAL: Unhandled Promise Rejection detected:", reason);
  // في بيئة الإنتاج: يفضل تسجيل الخطأ ثم إغلاق السيرفر بنظام Graceful Shutdown
});

process.on("uncaughtException", (error: Error) => {
  console.error("FATAL: Uncaught Exception! Process is unstable:", error);
  // الخروج الإلزامي لأن حالة ذاكرة التطبيق بقت غير موثوقة
  process.exit(1);
});

