import express, { Request, Response } from "express";
import * as crypto from "node:crypto";

// ==========================================
// 1. استهلاك API خارجي بصمود وأمان (Resilient HTTP Client)
// ==========================================
export interface ExternalFetchOptions {
  timeoutMs?: number;
  maxRetries?: number;
}

export async function fetchWithRetryAndTimeout<T>(
  url: string,
  options: RequestInit = {},
  config: ExternalFetchOptions = {}
): Promise<T> {
  const timeoutMs = config.timeoutMs || 5000;
  const maxRetries = config.maxRetries || 3;

  let attempt = 0;

  while (attempt < maxRetries) {
    attempt++;
    try {
      // دمج مهلة الاتصال بالـ AbortSignal
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

      const response = await fetch(url, {
        ...options,
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      // في حالة النجاح
      if (response.ok) {
        return (await response.json()) as T;
      }

      // أخطاء العميل (4xx ما عدا 429) لا تستدعي إعادة المحاولة
      if (response.status >= 400 && response.status < 500 && response.status !== 429) {
        throw new Error(`Client error: ${response.status} - ${response.statusText}`);
      }

      throw new Error(`Server returned status: ${response.status}`);
    } catch (error: any) {
      const isLastAttempt = attempt >= maxRetries;
      if (isLastAttempt) {
        console.error(`FATAL: External call to ${url} failed after ${maxRetries} attempts. Error:`, error.message);
        throw error;
      }

      // حساب وقت الانتظار بالتراجع الأسي والتشتت (Exponential Backoff + Jitter)
      const baseDelay = Math.pow(2, attempt) * 1000;
      const jitter = Math.floor(Math.random() * 500);
      const totalDelay = baseDelay + jitter;

      console.warn(`Attempt ${attempt} to ${url} failed. Retrying in ${totalDelay}ms...`);
      await new Promise((resolve) => setTimeout(resolve, totalDelay));
    }
  }

  throw new Error("Unexpected end of retry loop.");
}

// ==========================================
// 2. التحقق من توقيع الـ Webhook (HMAC Verification)
// ==========================================
export class WebhookSecurity {
  public static verifyHmacSignature(
    rawPayload: string | Buffer,
    receivedSignature: string,
    secret: string
  ): boolean {
    const computedSignature = crypto
      .createHmac("sha256", secret)
      .update(rawPayload)
      .digest("hex");

    // مقارنة آمنة ضد هجمات تسريب التوقيت (Timing-Safe Comparison)
    const computedBuffer = Buffer.from(computedSignature, "utf8");
    const receivedBuffer = Buffer.from(receivedSignature, "utf8");

    if (computedBuffer.length !== receivedBuffer.length) {
      return false;
    }

    return crypto.timingSafeEqual(computedBuffer, receivedBuffer);
  }
}

// ==========================================
// 3. مسار استقبال الـ Webhook في Express
// ==========================================
const app = express();

// ملاحظة حرجة: الـ Webhook يحتاج الـ Raw Body للتحقق من التوقيع
app.post(
  "/api/v1/webhooks/payments",
  express.raw({ type: "application/json" }), // استقبال البيانات كـ Buffer خام
  async (req: Request, res: Response): Promise<void> => {
    const signature = req.headers["x-webhook-signature"] as string;
    const webhookSecret = process.env.WEBHOOK_SECRET || "whsec_super_secret_test_key";

    if (!signature) {
      res.status(400).json({ error: "Missing signature header." });
      return;
    }

    // 1. التحقق من التوقيع التشفيري
    const isValid = WebhookSecurity.verifyHmacSignature(req.body, signature, webhookSecret);
    if (!isValid) {
      console.error("SECURITY ALERT: Invalid webhook signature received!");
      res.status(400).json({ error: "Invalid signature verification failed." });
      return;
    }

    // 2. فك الـ JSON بعد التأكد من صحة التوقيع
    const payload = JSON.parse(req.body.toString());
    const eventId = payload.id;

    // 3. التحقق من عدم معالجة الحدث مسبقاً (Idempotency Check)
    const isAlreadyProcessed = false; // محاكاة فحص قاعدة البيانات
    if (isAlreadyProcessed) {
      res.status(200).json({ received: true, note: "Already processed" });
      return;
    }

    // 4. الرد الفوري بـ 200 OK لتفادي الـ Timeout من جهة البنك
    res.status(200).json({ received: true });

    // 5. تفويض معالجة البيانات الثقيلة لخلفية النظام (Background Job)
    console.log(`Successfully acknowledged event: ${eventId}. Offloading to Worker...`);
  }
);

import { Request, Response } from "express";
import Redis from "ioredis";
import { Queue, Worker, Job } from "bullmq";

// 1. إعداد اتصال Redis المشترك
const REDIS_HOST = process.env.REDIS_HOST || "localhost";
const REDIS_PORT = Number(process.env.REDIS_PORT) || 6379;

export const redisClient = new Redis({
  host: REDIS_HOST,
  port: REDIS_PORT,
  maxRetriesPerRequest: null
});

// ==========================================
// 2. موديول الـ Caching المساعد (Cache Service)
// ==========================================
export class CacheService {
  // جلب البيانات من الكاش أو استخراجها من قاعدة البيانات وحفظها (Cache-Aside)
  public static async getOrSet<T>(
    key: string,
    ttlSeconds: number,
    fetchFunction: () => Promise<T>
  ): Promise<T> {
    // 1. محاولة القراءة من Redis
    const cachedData = await redisClient.get(key);
    if (cachedData) {
      return JSON.parse(cachedData) as T;
    }

    // 2. في حالة Cache Miss: تنفيذ دالة جلب البيانات الأصلية
    const freshData = await fetchFunction();

    // 3. تخزين النتيجة في Redis مع تحديد عمر الـ TTL
    if (freshData !== null && freshData !== undefined) {
      await redisClient.set(key, JSON.stringify(freshData), "EX", ttlSeconds);
    }

    return freshData;
  }

  // إبطال وحذف مفتاح من الكاش عند التعديل
  public static async invalidate(key: string): Promise<void> {
    await redisClient.del(key);
  }
}

// ==========================================
// 3. إعداد طابور المهام الخلفية (BullMQ Queue)
// ==========================================
export interface WelcomeEmailJobData {
  userId: string;
  email: string;
  fullName: string;
}

// إنشاء الطابور (Producer Side)
export const emailQueue = new Queue<WelcomeEmailJobData>("email-delivery-queue", {
  connection: { host: REDIS_HOST, port: REDIS_PORT }
});

// ==========================================
// 4. إنشاء العامل الخلفي (Background Worker Consumer)
// ==========================================
export const emailWorker = new Worker<WelcomeEmailJobData>(
  "email-delivery-queue",
  async (job: Job<WelcomeEmailJobData>) => {
    console.log(`[WORKER] Processing Job ID: ${job.id} for user: ${job.data.email}`);

    // محاكاة إرسال إيميل خارجي قد يستغرق 3 ثوانٍ
    await new Promise((resolve) => setTimeout(resolve, 2000));

    // محاكاة فشل عشوائي لاختبار الـ Retries
    if (Math.random() < 0.1) {
      throw new Error("SMTP_CONNECTION_TIMEOUT: Mail server unavailable.");
    }

    console.log(`[WORKER] Successfully sent welcome email to: ${job.data.email}`);
  },
  {
    connection: { host: REDIS_HOST, port: REDIS_PORT },
    concurrency: 5 // معالجة 5 إيميلات بالتوازي في نفس اللحظة
  }
);

// الاستماع لأحداث العمال لمراقبة الأعطال
emailWorker.on("failed", (job, err) => {
  console.error(`[WORKER ALERT] Job ${job?.id} failed on attempt ${job?.attemptsMade}. Reason:`, err.message);
});

// ==========================================
// 5. استخدام الكاش والـ Queue جوه الـ Controller
// ==========================================
export class ProductController {
  // GET /api/v1/products/featured (محمي بـ Redis Cache لمدة 5 دقائق)
  public static async getFeaturedProducts(req: Request, res: Response): Promise<void> {
    const cacheKey = "products:featured:list";

    const products = await CacheService.getOrSet(cacheKey, 300, async () => {
      console.log("CACHE MISS: Fetching from PostgreSQL Database...");
      // محاكاة استعلام داتابيز بطيء
      return [
        { id: "p1", name: "Ergonomic Chair", price: 300 },
        { id: "p2", name: "Standing Desk", price: 600 }
      ];
    });

    res.status(200).json({ success: true, source: "cached-or-computed", data: products });
  }

  // POST /api/v1/auth/register (يضيف مهمة إرسال الإيميل للـ Queue فوراً)
  public static async registerUser(req: Request, res: Response): Promise<void> {
    const { email, fullName } = req.body;

    // 1. حفظ المستخدم في قاعدة البيانات (سريع)
    const newUser = { id: `usr_${Date.now()}`, email, fullName };

    // 2. إلقاء مهمة الإيميل في الـ Queue مع سياسة إعادة محاولة ذكية
    await emailQueue.add(
      "send-welcome-email",
      { userId: newUser.id, email: newUser.email, fullName: newUser.fullName },
      {
        attempts: 3, // إعادة المحاولة حتى 3 مرات
        backoff: { type: "exponential", delay: 2000 }, // تراجع أسي
        removeOnComplete: true // تنظيف الذاكرة بعد النجاح
      }
    );

    // 3. الرد الفوري على المستخدم في أقل من 20ms من غير انتظار إرسال الإيميل!
    res.status(201).json({
      success: true,
      message: "User registered successfully. Welcome email is queued.",
      data: newUser
    });
  }
}

