import { describe, it, expect, beforeAll, afterAll } from "vitest";
import request from "supertest";
import { app } from "../../src/app.js";
import { DatabasePool } from "../../src/infrastructure/database.js";
import { SecurityUtils } from "../../src/utils/security.js";

describe("POST /api/v1/orders — Integration Tests", () => {
  let validAuthToken: string;

  beforeAll(async () => {
    // توليد توكن اختبار موثق
    validAuthToken = SecurityUtils.generateAccessToken({
      userId: "usr_test_99",
      email: "tester@example.com",
      role: "customer"
    });
  });

  it("should reject the request with 401 Unauthorized if token is missing", async () => {
    const res = await request(app)
      .post("/api/v1/orders")
      .send({ rawAmount: 150.00 });

    expect(res.status).toBe(401);
    expect(res.body.success).toBe(false);
