});

import express, { Request, Response } from "express";
import http from "node:http";
import pino from "pino";
import compression from "compression";
import { DatabasePool } from "./infrastructure/database.js";
import { redisClient } from "./infrastructure/redis.js";

// 1. إعداد الـ Structured Logger باستخدام Pino
export const logger = pino({
  level: process.env.LOG_LEVEL || "info",
  timestamp: pino.stdTimeFunctions.isoTime,
  formatters: {
    level: (label) => ({ level: label.toUpperCase() })
  }
});

const app = express();

// تفعيل ضغط الاستجابات (Gzip/Brotli) لتسريع نقل الـ JSON عبر الشبكة
app.use(compression());
app.use(express.json());

// 2. فحص الحياة (Liveness Probe)
app.get("/health/liveness", (req: Request, res: Response) => {
  res.status(200).json({ status: "alive", uptime: process.uptime() });
});

// 3. فحص الجاهزية (Readiness Probe)
app.get("/health/readiness", async (req: Request, res: Response): Promise<void> => {
  try {
    const dbPool = DatabasePool.getPool();

    // فحص اتصال قاعدة البيانات باستعلام سريع
    await dbPool.query("SELECT 1;");

    // فحص اتصال Redis
    const redisPing = await redisClient.ping();
    if (redisPing !== "PONG") {
      throw new Error("Redis ping failed");
    }

    res.status(200).json({
      status: "ready",
      services: { database: "connected", redis: "connected" }
    });
  } catch (error: any) {
    logger.error({ err: error.message }, "Readiness check failed!");
    res.status(503).json({
      status: "unavailable",
      error: "Critical dependency is not responding"
    });
  }
});

// 4. إنشاء وتشغيل السيرفر
const PORT = Number(process.env.PORT) || 3000;
const server = http.createServer(app);

server.listen(PORT, () => {
  logger.info(`Production Server successfully bound to port: ${PORT}`);
});

// ==========================================
// 5. بروتوكول الإغلاق السليم (Graceful Shutdown Handler)
// ==========================================
let isShuttingDown = false;

function initiateGracefulShutdown(signal: string) {
  if (isShuttingDown) return;
  isShuttingDown = true;

  logger.warn(`Received signal: ${signal}. Initiating Graceful Shutdown sequence...`);

  // تحديد مهلة أمان قصوى للإغلاق القسري لو علق أي اتصال (15 ثانية)
  const forceShutdownTimer = setTimeout(() => {
    logger.error("Graceful shutdown timeout exceeded (15s). Forcing process exit!");
    process.exit(1);
  }, 15000);
  forceShutdownTimer.unref();

  // 1. التوقف عن قبول اتصالات جديدة
  server.close(async (err) => {
    if (err) {
      logger.error({ err }, "Error occurred while closing HTTP server.");
      process.exit(1);
    }

    logger.info("HTTP Server closed. No more incoming requests accepted.");

    try {
      // 2. إغلاق مجمع اتصالات قاعدة البيانات بأمان
      const dbPool = DatabasePool.getPool();
      await dbPool.end();
      logger.info("PostgreSQL Database Pool drained and closed.");

      // 3. إغلاق اتصال Redis
      await redisClient.quit();
      logger.info("Redis connection closed cleanly.");

      logger.info("Graceful Shutdown completed successfully. Goodbye!");
      process.exit(0);
    } catch (cleanupError) {
      logger.error({ err: cleanupError }, "Error during dependency cleanup.");
      process.exit(1);
    }
  });
}

// الاستماع لإشارات الإيقاف الصادرة من نظام التشغيل أو Docker
process.on("SIGTERM", () => initiateGracefulShutdown("SIGTERM"));
process.on("SIGINT", () => initiateGracefulShutdown("SIGINT"));

import { z } from "zod";

const EnvironmentSchema = z.object({
  NODE_ENV: z.enum(["development", "production", "test"]).default("development"),
  PORT: z.coerce.number().default(3000),
  DATABASE_URL: z.string().url(),
  REDIS_HOST: z.string().default("localhost"),
  REDIS_PORT: z.coerce.number().default(6379),
  JWT_SECRET: z.string().min(32, "JWT Secret must be at least 32 characters for security"),
  WEBHOOK_SECRET: z.string().min(16),
  ALLOWED_ORIGIN: z.string().default("http://localhost:5173")
});

export type Environment = z.infer<typeof EnvironmentSchema>;

export function loadConfig(): Environment {
  const result = EnvironmentSchema.safeParse(process.env);
  if (!result.success) {
    console.error("FATAL CONFIG ERROR: Invalid environment variables configuration:", result.error.format());
    process.exit(1);
  }
  return result.data;
}

export const env = loadConfig();

import { Pool, PoolClient } from "pg";
import { AppError } from "../../middlewares/error.middleware.js";

export interface OrderRecord {
  id: string;
  userId: string;
  productId: string;
  quantity: number;
  totalPrice: number;
  status: "pending" | "completed" | "cancelled";
  createdAt: Date;
}

export class PostgresOrderRepository {
  constructor(private readonly pool: Pool) {}

  public async createOrderWithInventoryDeduction(
    userId: string,
    productId: string,
    quantity: number
  ): Promise<OrderRecord> {
    const client: PoolClient = await this.pool.connect();

    try {
      await client.query("BEGIN;");

      // 1. القفل المتشائم للمنتج لمنع الـ Race Condition في المخزون
      const productRes = await client.query(
        `SELECT id, name, price, stock FROM products WHERE id = $1 FOR UPDATE;`,
        [productId]
      );

      if (productRes.rows.length === 0) {
        throw new AppError("Product not found", 404, "PRODUCT_NOT_FOUND");
      }

      const product = productRes.rows[0];
      if (product.stock < quantity) {
        throw new AppError("Insufficient warehouse stock", 422, "OUT_OF_STOCK", {
          available: product.stock,
          requested: quantity
        });
      }

      const totalPrice = Number(product.price) * quantity;

      // 2. خصم المخزون
      await client.query(
        `UPDATE products SET stock = stock - $1, updated_at = NOW() WHERE id = $2;`,
        [quantity, productId]
      );

      // 3. إنشاء سجل الطلب
      const orderRes = await client.query(
        `INSERT INTO orders (user_id, product_id, quantity, total_price, status) 
         VALUES ($1, $2, $3, $4, 'completed') 
         RETURNING id, user_id, product_id, quantity, total_price, status, created_at;`,
        [userId, productId, quantity, totalPrice]
      );

      await client.query("COMMIT;");

      const row = orderRes.rows[0];
      return {
        id: row.id,
        userId: row.user_id,
        productId: row.product_id,
        quantity: row.quantity,
        totalPrice: Number(row.total_price),
        status: row.status,
        createdAt: row.created_at
      };
    } catch (error) {
      await client.query("ROLLBACK;");
      throw error;
    } finally {
      client.release();
    }
  }
}

import { PostgresOrderRepository, OrderRecord } from "./order.repository.js";
import { emailQueue } from "../../jobs/queue.js";
import { logger } from "../../infrastructure/logger.js";

export class OrderService {
  constructor(private readonly orderRepository: PostgresOrderRepository) {}

  public async processCheckout(
    userId: string,
    userEmail: string,
    productId: string,
    quantity: number
  ): Promise<OrderRecord> {
    logger.info({ userId, productId, quantity }, "Initiating checkout process...");

    // 1. تنفيذ العملية الذرية في قاعدة البيانات
    const order = await this.orderRepository.createOrderWithInventoryDeduction(
      userId,
      productId,
      quantity
    );

    // 2. إلقاء مهمة إرسال الفاتورة بالبريد في طابور Redis للـ Worker
    await emailQueue.add(
      "send-order-confirmation",
      {
        orderId: order.id,
        email: userEmail,
        totalPrice: order.totalPrice
      },
      {
        attempts: 3,
        backoff: { type: "exponential", delay: 1000 }
      }
    );

    logger.info({ orderId: order.id }, "Order successfully placed and confirmation queued.");
    return order;
  }
}

import express from "express";
import helmet from "helmet";
import cors from "cors";
import compression from "compression";
import rateLimit from "express-rate-limit";
import { env } from "./config/environment.js";
import { errorHandlerMiddleware } from "./middlewares/error.middleware.js";
import { DatabasePool } from "./infrastructure/database.js";
import { redisClient } from "./infrastructure/redis.js";

const app = express();

// 1. ترويسات الأمان والضغط والـ CORS
app.use(helmet());
app.use(compression());
app.use(
  cors({
    origin: env.ALLOWED_ORIGIN,
    credentials: true
  })
);

// 2. مسار الـ Webhooks يستقبل الـ Raw Buffer (قبل express.json)
app.use("/api/v1/webhooks", express.raw({ type: "application/json" }));

// 3. تحليل الـ JSON مع تقييد الحجم
app.use(express.json({ limit: "1mb" }));

// 4. Rate Limiting العام
app.use(
  rateLimit({
    windowMs: 60 * 1000,
    max: 100,
    standardHeaders: true
  })
);

// 5. مسارات فحص الصحة للإنتاج (Health Checks)
app.get("/health/liveness", (req, res) => res.status(200).json({ status: "alive" }));
app.get("/health/readiness", async (req, res) => {
  try {
    await DatabasePool.getPool().query("SELECT 1;");
    await redisClient.ping();
    res.status(200).json({ status: "ready" });
  } catch {
    res.status(503).json({ status: "unhealthy" });
  }
});

// 6. تسجيل الميدلوير المركزي للأخطاء في الآخر خالص
app.use(errorHandlerMiddleware);

export { app };
